function b64url(buf) { return Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=/g, ''); }
function signToken(phone) {
  const now = Math.floor(Date.now() / 1000);
  const header = b64url(Buffer.from(JSON.stringify({ alg: 'HS256', typ: 'JWT' })));
  const body = b64url(Buffer.from(JSON.stringify({ phone, iat: now, exp: now + 30 * 24 * 60 * 60 })));
  return `${header}.${body}.${b64url(hmacSha256($env.JWT_SECRET, `${header}.${body}`))}`;
}
function verifyToken(headers) {
  const auth = String((headers || {}).authorization || '').trim();
  const token = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';
  if (!token) return { ok: false, error: 'Please log in again.' };
  const parts = token.split('.');
  if (parts.length !== 3) return { ok: false, error: 'Please log in again.' };
  const [h, p, s] = parts;
  if (b64url(hmacSha256($env.JWT_SECRET, `${h}.${p}`)) !== s) return { ok: false, error: 'Please log in again.' };
  let claims;
  try { claims = JSON.parse(Buffer.from(p, 'base64').toString('utf8')); } catch { return { ok: false, error: 'Please log in again.' }; }
  if (!claims.exp || claims.exp < Math.floor(Date.now() / 1000)) return { ok: false, error: 'Your session expired. Please log in again.' };
  if (!/^[6-9]\d{9}$/.test(String(claims.phone || ''))) return { ok: false, error: 'Please log in again.' };
  return { ok: true, phone: String(claims.phone) };
}


const auth = verifyToken($in.headers);
if (!auth.ok) return [{ json: { ok: false, status: 401, body: { success: false, message: auth.error } } }];
const b = $in.body || {};
const bad = (m, status = 422) => [{ json: { ok: false, status, body: { success: false, message: m } } }];
const str = v => String(v ?? '').trim().replace(/\s+/g, ' ');

const code = str(b.code).toUpperCase(), action = str(b.action).toUpperCase();
if (!/^[A-Z0-9]{6}$/.test(code)) return bad('Invalid match link.', 404);
if (!['JOIN', 'LEAVE', 'SET_CAPTAIN', 'ASSIGN', 'SHUFFLE', 'CANCEL'].includes(action)) return bad('Invalid request.');
const side = b.side == null ? null : str(b.side).toUpperCase(), target = b.user_id == null ? null : Number(b.user_id);
if (action === 'SET_CAPTAIN' && (!['HOME', 'AWAY'].includes(side) || !(Number.isInteger(target) && target > 0))) return bad('Pick a captain.');
// ASSIGN: put a player in a team (side HOME / AWAY) or take them out of both (side null).
